139→  0%, 100% { opacity: 1; }
140→  50% { opacity: 0.6; }
141→}
142→
143→/* ── Messages Area ──────────────────────────────────────────────── */
144→
145→.sd-messages {
146→  flex: 1;
147→  overflow-y: auto;
148→  padding: var(--sd-space-xl) var(--sd-space-lg);
149→  display: flex;
150→  flex-direction: column;
151→  gap: var(--sd-msg-gap);
152→  background: var(--sd-canvas);
153→}
154→
155→/* ── Message Bubbles ────────────────────────────────────────────── */
156→
157→.sd-message {
158→  display: flex;
159→  flex-direction: column;
160→  gap: var(--sd-space-sm);
161→  padding: var(--sd-space-lg) var(--sd-space-xl);
162→  border-radius: 8px;
163→  font-family: var(--sd-font-sans);
164→  font-size: 13px;
165→  line-height: 1.7;
166→  word-wrap: break-word;
167→}
168→
169→.sd-message--user {
170→  background: var(--sd-card);
171→  align-self: flex-end;
172→  max-width: 90%;
173→  border: 1px solid var(--sd-border-subtle);
174→}
175→
176→.sd-message--agent {
177→  background: var(--sd-panel);
178→  align-self: flex-start;
179→  max-width: 95%;
180→  border-left: 2px solid var(--sd-accent-dim);
181→}
182→
183→.sd-message--system {
184→  background: transparent;
185→  color: var(--sd-text-muted);
186→  font-style: italic;
187→  font-size: 11px;
188→  align-self: center;
189→}
190→
191→.sd-message__label {
192→  font-family: var(--sd-font-mono);
193→  font-size: 10.5px;
194→  font-weight: 400;
195→  color: var(--sd-text-muted);
196→  text-transform: uppercase;
197→  letter-spacing: 0.06em;
198→  margin-bottom: 2px;
199→}
200→
201→.sd-message--user .sd-message__label {
202→  color: var(--sd-text-accent);
203→}
204→
205→.sd-message--agent .sd-message__label {
206→  color: var(--sd-accent);
207→}
208→
209→.sd-message__body {
210→  color: var(--sd-text-secondary);
211→}
212→
213→.sd-message--user .sd-message__body {
214→  color: var(--sd-text-primary);
215→}
216→
217→.sd-message--system .sd-message__body {
218→  color: var(--sd-text-muted);
219→}
220→
221→/* Visual breathing line between consecutive agent messages */
222→.sd-message--agent + .sd-message--agent {
223→  padding-top: var(--sd-space-xl);
224→  border-top: 1px solid var(--sd-border-subtle);
225→  margin-top: var(--sd-space-xs);
226→}
227→
228→/* ── Text Rendering Classes ─────────────────────────────────────── */
229→
230→.sd-text-body {
231→  font-family: var(--sd-font-sans);
232→  font-size: 13px;
233→  color: var(--sd-text-secondary);
234→  line-height: 1.7;
235→}
236→
237→.sd-text-body p {
238→  margin: 0 0 var(--sd-para-gap) 0;
239→}
240→
241→.sd-text-body p:last-child {
242→  margin-bottom: 0;
243→}
244→
245→.sd-code-inline {
246→  font-family: var(--sd-font-mono);
247→  font-size: 11px;
248→  background: var(--sd-elevated);
249→  color: var(--sd-text-accent);
250→  padding: 2px 7px;
251→  border-radius: 3px;
252→  letter-spacing: 0.01em;
253→}
254→
255→.sd-code-block {
256→  font-family: var(--sd-font-mono);
257→  font-size: 11.5px;
258→  line-height: 1.65;
259→  background: var(--sd-input);
260→  color: var(--sd-text-primary);
261→  padding: var(--sd-space-lg) var(--sd-space-xl);
262→  border-radius: 4px;
263→  border: 1px solid var(--sd-border-subtle);
264→  margin: var(--sd-space-lg) 0;
265→  overflow-x: auto;
266→  white-space: pre;
267→}
268→
269→.sd-text-bold {
270→  font-weight: 600;
271→  color: var(--sd-text-primary);
272→}
273→
274→/* ── Typing Indicator ───────────────────────────────────────────── */
275→
276→.sd-typing {
277→  display: inline-flex;
278→  align-items: center;
279→  gap: 4px;
280→  padding: 4px 0;
281→}
282→
283→.sd-typing__dot {
284→  width: 5px;
285→  height: 5px;
286→  border-radius: 50%;
287→  background: var(--sd-accent);
288→  animation: sd-typing-pulse 1.2s ease-in-out infinite;
289→}
290→
291→.sd-typing__dot:nth-child(2) {
292→  animation-delay: 0.15s;
293→}
294→
295→.sd-typing__dot:nth-child(3) {
296→  animation-delay: 0.3s;
297→}
298→
299→@keyframes sd-typing-pulse {
300→  0%, 60%, 100% { opacity: 0.3; transform: scale(0.8); }
301→  30% { opacity: 1; transform: scale(1); }
302→}
303→
304→/* ── Input Bar ──────────────────────────────────────────────────── */
305→
306→.sd-input-bar {
307→  display: flex;
308→  gap: var(--sd-space-sm);
309→  padding: var(--sd-space-lg) var(--sd-space-xl);
310→  border-top: 1px solid var(--sd-border);
311→  background: var(--sd-panel);
312→  flex-shrink: 0;
313→}
314→
315→.sd-input {
316→  flex: 1;
317→  background: var(--sd-input);
318→  border: 1px solid var(--sd-border);
319→  border-radius: 6px;
320→  padding: var(--sd-space-md) 10px;
321→  color: var(--sd-text-primary);
322→  font-family: var(--sd-font-sans);
323→  font-size: 12px;
324→  outline: none;
325→  transition: border-color var(--sd-transition);
326→}
327→
328→.sd-input:focus {
329→  border-color: var(--sd-accent);
330→}
331→
332→.sd-input::placeholder {
333→  color: var(--sd-text-muted);
334→}
335→
336→.sd-send-btn {
337→  background: var(--sd-accent);
338→  color: #1a1a1a;
339→  border: none;
340→  border-radius: 6px;
341→  padding: var(--sd-space-md) 14px;
342→  font-family: var(--sd-font-sans);
343→  font-size: 12px;
344→  font-weight: 600;
345→  cursor: pointer;
346→  transition: background var(--sd-transition), opacity var(--sd-transition);
347→  flex-shrink: 0;
348→}
349→
350→.sd-send-btn:hover {
351→  opacity: 0.9;
352→}
353→
354→.sd-send-btn:active {
355→  opacity: 0.8;
356→}
357→
358→.sd-send-btn:disabled {
359→  background: var(--sd-elevated);
360→  color: var(--sd-text-muted);
361→  cursor: not-allowed;
362→  opacity: 1;
363→}
364→
365→/* ── Scrollbar ──────────────────────────────────────────────────── */
366→
367→.sd-messages::-webkit-scrollbar {
368→  width: 3px;
369→}
370→
371→.sd-messages::-webkit-scrollbar-track {
372→  background: transparent;
373→}
374→
375→.sd-messages::-webkit-scrollbar-thumb {
376→  background: var(--sd-border);
377→  border-radius: 2px;
378→}
379→
380→.sd-messages::-webkit-scrollbar-thumb:hover {
381→  background: var(--sd-text-muted);
382→}
383→
384→/* ── Panel Components ───────────────────────────────────────────── */
385→
386→/* Panel container */
387→.sd-panel {
388→  background: var(--sd-panel);
389→  border-radius: 6px;
390→  border: 1px solid var(--sd-border-subtle);
391→  overflow: hidden;
392→  margin: var(--sd-space-xs) 0;
393→  max-width: 100%;
394→}
395→
396→/* Panel header */
397→.sd-panel__header {
398→  padding: var(--sd-space-xl) 14px 14px;
399→}
400→
401→.sd-panel__label-row {
402→  display: flex;
403→  align-items: center;
404→  justify-content: space-between;
405→  margin-bottom: var(--sd-space-md);
406→}
407→
408→.sd-panel__label {
409→  font-family: var(--sd-font-mono);
410→  font-size: 10px;
411→  font-weight: 400;
412→  color: var(--sd-text-muted);
413→  text-transform: uppercase;
414→  letter-spacing: 0.06em;
415→}
416→
417→.sd-panel__badge {
418→  font-family: var(--sd-font-mono);
419→  font-size: 10px;
420→  font-weight: 400;
421→  color: var(--sd-accent);
422→  background: var(--sd-accent-subtle);
423→  padding: 2px 8px;
424→  border-radius: 3px;
425→  letter-spacing: 0.01em;
426→}
427→
428→.sd-panel__title {
429→  font-family: var(--sd-font-sans);
430→  font-size: 16px;
431→  font-weight: 600;
432→  color: var(--sd-text-primary);
433→  letter-spacing: -0.02em;
434→  margin-bottom: var(--sd-space-sm);
435→  line-height: 1.3;
436→}
437→
438→.sd-panel__summary {
439→  font-family: var(--sd-font-sans);
440→  font-size: 12px;
441→  color: var(--sd-text-secondary);
442→  line-height: 1.5;
443→  margin-bottom: var(--sd-space-lg);
444→}
445→
446→.sd-panel__stats {
447→  display: flex;
448→  gap: var(--sd-space-xl);
449→}
450→
451→.sd-panel__stat {
452→  display: flex;
453→  flex-direction: column;
454→  gap: 1px;
455→}
456→
457→.sd-panel__stat-value {
458→  font-family: var(--sd-font-mono);
459→  font-size: 14px;
460→  font-weight: 600;
461→  color: var(--sd-text-primary);
462→}
463→
464→.sd-panel__stat-label {
465→  font-family: var(--sd-font-sans);
466→  font-size: 10px;
467→  color: var(--sd-text-muted);
468→}
469→
470→/* Collapsible section */
471→.sd-section {
472→  border-top: 1px solid var(--sd-border-subtle);
473→}
474→
475→.sd-section__trigger {
476→  display: flex;
477→  align-items: center;
478→  width: 100%;
479→  padding: 10px 14px;
480→  background: none;
481→  border: none;
482→  cursor: pointer;
483→  color: var(--sd-text-primary);
484→  font-family: var(--sd-font-sans);
485→  font-size: 12px;
486→  font-weight: 500;
487→  letter-spacing: 0.01em;
488→  text-align: left;
489→  gap: var(--sd-space-md);
490→  transition: background var(--sd-transition);
491→}
492→
493→.sd-section__trigger:hover {
494→  background: var(--sd-card);
495→}
496→
497→.sd-section__dot {
498→  width: 5px;
499→  height: 5px;
500→  border-radius: 50%;
501→  flex-shrink: 0;
502→}
503→
504→.sd-section__title {
505→  flex: 1;
506→}
507→
508→.sd-section__count {
509→  font-family: var(--sd-font-mono);
510→  font-size: 10px;
511→  color: var(--sd-text-muted);
512→  letter-spacing: 0.01em;
513→}
514→
515→.sd-section__chevron {
516→  font-size: 10px;
517→  color: var(--sd-text-muted);
518→  transition: transform var(--sd-transition);
519→  flex-shrink: 0;
520→}
521→
522→.sd-section--open > .sd-section__trigger .sd-section__chevron {
523→  transform: rotate(90deg);
524→}
525→
526→.sd-section__body {
527→  padding: 0 14px 12px;
528→  display: none;
529→}
530→
531→.sd-section--open > .sd-section__body {
532→  display: block;
533→}
534→
535→/* Slot tag */
536→.sd-slot-tag {
537→  display: inline-flex;
538→  align-items: center;
539→  gap: var(--sd-space-xs);
540→  padding: 2px 8px 2px 6px;
541→  border-radius: 3px;
542→  font-family: var(--sd-font-mono);
543→  font-size: 11px;
544→  letter-spacing: 0.01em;
545→  margin: 0 var(--sd-space-xs) var(--sd-space-xs) 0;
546→}
547→
548→.sd-slot-tag__dot {
549→  width: 5px;
550→  height: 5px;
551→  border-radius: 50%;
552→  flex-shrink: 0;
553→}
554→
555→/* Flow chain */
556→.sd-flow-chain {
557→  display: flex;
558→  flex-wrap: wrap;
559→  align-items: center;
560→  gap: 2px;
561→  padding: var(--sd-space-xs) 0;
562→}
563→
564→.sd-flow-chain__label {
565→  font-family: var(--sd-font-mono);
566→  font-size: 10px;
567→  color: var(--sd-text-muted);
568→  text-transform: uppercase;
569→  letter-spacing: 0.06em;
570→  margin-right: var(--sd-space-md);
571→  width: 100%;
572→  margin-bottom: var(--sd-space-xs);
573→}
574→
575→.sd-flow-chain__node {
576→  font-family: var(--sd-font-mono);
577→  font-size: 11px;
578→  padding: 2px 6px;
579→  border-radius: 3px;
580→  letter-spacing: 0.01em;
581→  white-space: nowrap;
582→}
583→
584→.sd-flow-chain__arrow {
585→  color: var(--sd-text-muted);
586→  font-size: 10px;
587→  padding: 0 2px;
588→  user-select: none;
589→}
590→
591→/* Detail row */
592→.sd-detail-row {
593→  display: flex;
594→  align-items: baseline;
595→  gap: var(--sd-space-md);
596→  padding: var(--sd-space-xs) 0;
597→}
598→
599→.sd-detail-row__label {
600→  font-family: var(--sd-font-sans);
601→  font-size: 11px;
602→  color: var(--sd-text-muted);
603→  white-space: nowrap;
604→}
605→
606→.sd-detail-row__leader {
607→  flex: 1;
608→  border-bottom: 1px dotted var(--sd-border);
609→  min-width: 16px;
610→  margin-bottom: 3px;
611→}
612→
613→.sd-detail-row__value {
614→  font-family: var(--sd-font-mono);
615→  font-size: 10.5px;
616→  color: var(--sd-text-secondary);
617→  letter-spacing: 0.01em;
618→  white-space: nowrap;
619→  text-align: right;
620→}
621→
622→/* Capability row */
623→.sd-capability-row {
624→  display: flex;
625→  align-items: baseline;
626→  gap: var(--sd-space-md);
627→  padding: var(--sd-space-xs) 0;
628→}
629→
630→.sd-capability-row__dot {
631→  width: 4px;
632→  height: 4px;
633→  border-radius: 50%;
634→  flex-shrink: 0;
635→  margin-top: 5px;
636→}
637→
638→.sd-capability-row__label {
639→  font-family: var(--sd-font-sans);
640→  font-size: 11px;
641→  font-weight: 500;
642→  color: var(--sd-text-accent);
643→  white-space: nowrap;
644→}
645→
646→.sd-capability-row__sep {
647→  flex: 1;
648→  border-bottom: 1px solid var(--sd-border-subtle);
649→  min-width: 12px;
650→  margin-bottom: 3px;
651→}
652→
653→.sd-capability-row__desc {
654→  font-family: var(--sd-font-sans);
655→  font-size: 10.5px;
656→  color: var(--sd-text-muted);
657→  text-align: right;
658→}
659→
660→/* Action footer */
661→.sd-panel__footer {
662→  display: flex;
663→  align-items: center;
664→  justify-content: space-between;
665→  padding: 10px 14px;
666→  border-top: 1px solid var(--sd-border-subtle);
667→}
668→
669→.sd-panel__footer-status {
670→  font-family: var(--sd-font-mono);
671→  font-size: 10px;
672→  color: var(--sd-text-muted);
673→  letter-spacing: 0.01em;
674→}
675→
676→.sd-panel__footer-actions {
677→  display: flex;
678→  gap: var(--sd-space-sm);
679→}
680→
681→.sd-btn {
682→  font-family: var(--sd-font-sans);
683→  font-size: 11px;
684→  font-weight: 500;
685→  padding: 5px 14px;
686→  border-radius: 4px;
687→  cursor: pointer;
688→  transition: opacity var(--sd-transition), background var(--sd-transition);
689→}
690→
691→.sd-btn--secondary {
692→  background: transparent;
693→  border: 1px solid var(--sd-border);
694→  color: var(--sd-text-secondary);
695→}
696→
697→.sd-btn--secondary:hover {
698→  background: var(--sd-card);
699→}
700→
701→.sd-btn--primary {
702→  background: var(--sd-accent);
703→  border: none;
704→  color: #1a1a1a;
705→  font-weight: 600;
706→}
707→
708→.sd-btn--primary:hover {
709→  opacity: 0.9;
710→}
711→
712→/* Slot tags container */
713→.sd-slot-tags {
714→  display: flex;
715→  flex-wrap: wrap;
716→  gap: var(--sd-space-xs);
717→  padding: var(--sd-space-xs) 0;
718→}
719→
720→/* ── Node Pills (inline interactive node indicators) ─────────────── */
721→
722→.sd-node-pill {
723→  display: inline-flex;
724→  align-items: center;
725→  gap: 4px;
726→  padding: 2px 10px 2px 7px;
727→  border-radius: 10px;
728→  font-family: var(--sd-font-mono);
729→  font-size: 11px;
730→  letter-spacing: 0.01em;
731→  background: color-mix(in srgb, var(--pill-color) 12%, transparent);
732→  border: 1px solid color-mix(in srgb, var(--pill-color) 25%, transparent);
733→  color: var(--pill-color);
734→  transition: background var(--sd-transition), border-color var(--sd-transition);
735→  white-space: nowrap;
736→  margin: 0 3px;
737→  vertical-align: middle;
738→}
739→
740→.sd-node-pill:hover {
741→  background: color-mix(in srgb, var(--pill-color) 22%, transparent);
742→  border-color: color-mix(in srgb, var(--pill-color) 45%, transparent);
743→}
744→
745→.sd-node-pill[style*="cursor: pointer"]:active {
746→  transform: scale(0.97);
747→}
748→
749→.sd-node-pill__dot {
750→  width: 5px;
751→  height: 5px;
752→  border-radius: 50%;
753→  background: var(--pill-color);
754→  box-shadow: 0 0 5px color-mix(in srgb, var(--pill-color) 55%, transparent);
755→  flex-shrink: 0;
756→}
757→
758→/* Node activity message (shown in chat when tools touch nodes) */
759→.sd-message--node-activity {
760→  display: flex;
761→  align-items: center;
762→  flex-wrap: wrap;
763→  gap: 6px;
764→  padding: var(--sd-space-sm) var(--sd-space-xl);
765→  background: transparent;
766→  font-size: 11px;
767→  opacity: 0.85;
768→}
769→
770→.sd-node-activity__label {
771→  font-family: var(--sd-font-mono);
772→  font-size: 10px;
773→  font-weight: 400;
774→  color: var(--sd-text-muted);
775→  text-transform: uppercase;
776→  letter-spacing: 0.06em;
777→  margin-right: 4px;
778→}
779→
780→/* Node pills inside the stage bar */
781→.sd-stage-bar .sd-node-pill {
782→  font-size: 10px;
783→  padding: 1px 7px 1px 5px;
784→  margin-left: 4px;
785→}
786→
787→/* Long paragraphs get extra bottom margin for scanability */
788→.sd-para-long {
789→  margin-bottom: var(--sd-space-xl) !important;
790→}
791→
792→/* ── Readability Controls ──────────────────────────────────────── */
793→
794→.sd-readbar {
795→  display: flex;
796→  align-items: center;
797→  justify-content: flex-end;
798→  gap: 2px;
799→  padding: 3px var(--sd-space-xl) 3px var(--sd-space-lg);
800→  background: var(--sd-panel);
801→  border-top: 1px solid var(--sd-border-subtle);
802→  flex-shrink: 0;
803→  opacity: 0.4;
804→  transition: opacity 250ms ease;
805→}
806→
807→.sd-readbar:hover {
808→  opacity: 1;
809→}
810→
811→.sd-readbar__btn {
812→  display: flex;
813→  align-items: center;
814→  justify-content: center;
815→  width: 22px;
816→  height: 22px;
817→  border: none;
818→  background: transparent;
819→  color: var(--sd-text-muted);
820→  border-radius: 3px;
821→  cursor: pointer;
822→  padding: 0;
823→  transition: color var(--sd-transition), background var(--sd-transition);
824→}
825→
826→.sd-readbar__btn:hover {
827→  color: var(--sd-text-primary);
828→  background: var(--sd-card);
829→}
830→
831→.sd-readbar__btn--active {
832→  color: var(--sd-accent);
833→  background: var(--sd-accent-subtle);
834→}
835→
836→.sd-readbar__btn--active:hover {
837→  color: var(--sd-accent);
838→  background: var(--sd-accent-dim);
839→}
840→
841→.sd-readbar__btn svg {
842→  display: block;
843→}
844→
845→.sd-readbar__sep {
846→  width: 1px;
847→  height: 14px;
848→  background: var(--sd-border-subtle);
849→  margin: 0 3px;
850→  flex-shrink: 0;
851→}
852→
853→/* Font size text buttons */
854→.sd-readbar__btn--font-down {
855→  font-family: var(--sd-font-sans);
856→  font-size: 10px;
857→  font-weight: 700;
858→}
