  1→import { app } from "../../../scripts/app.js";
  2→import { renderText, createTypingIndicator, createPanel, createNodePill } from "./chat.js";
  3→
  4→/* ── SUPER DUPER Sidebar ─────────────────────────────────────────────
  5→ *  Registers a sidebar tab in ComfyUI's extension manager.
  6→ *  Chat interface with WebSocket connection to agent brain.
  7→ * ──────────────────────────────────────────────────────────────────── */
  8→
  9→const SIDEBAR_ID = "superduper";
 10→const SIDEBAR_TITLE = "Super Duper";
 11→
 12→/* ── Load stylesheet ──────────────────────────────────────────────── */
 13→
 14→const cssLink = document.createElement("link");
 15→cssLink.rel = "stylesheet";
 16→cssLink.href = new URL("../css/superduper.css", import.meta.url).href;
 17→document.head.appendChild(cssLink);
 18→
 19→/* ── Message rendering ────────────────────────────────────────────── */
 20→
 21→function createMessageEl(role, text) {
 22→  const msg = document.createElement("div");
 23→  msg.className = `sd-message sd-message--${role}`;
 24→
 25→  if (role !== "system") {
 26→    const label = document.createElement("span");
 27→    label.className = "sd-message__label";
 28→    label.textContent = role === "user" ? "You" : "Agent";
 29→    msg.appendChild(label);
 30→  }
 31→
 32→  const body = document.createElement("div");
 33→  body.className = "sd-message__body";
 34→
 35→  if (role === "agent") {
 36→    // Rich text rendering for agent messages
 37→    body.classList.add("sd-text-body");
 38→    body.appendChild(renderText(text));
 39→  } else {
 40→    // Plain text for user and system messages
 41→    body.textContent = text;
 42→  }
 43→
 44→  msg.appendChild(body);
 45→  return msg;
 46→}
 47→
 48→/* ── WebSocket connection ─────────────────────────────────────────── */
 49→
 50→class AgentConnection {
 51→  constructor(onMessage, onStatus) {
 52→    this.ws = null;
 53→    this.onMessage = onMessage;   // (event) => void
 54→    this.onStatus = onStatus;     // (status) => void
 55→    this.reconnectDelay = 1000;
 56→    this.maxReconnectDelay = 15000;
 57→    this.currentDelay = this.reconnectDelay;
 58→    this._closed = false;
 59→  }
 60→
 61→  connect() {
 62→    const proto = location.protocol === "https:" ? "wss:" : "ws:";
 63→    const url = `${proto}//${location.host}/superduper/ws`;
 64→
 65→    this.onStatus("connecting");
 66→    this.ws = new WebSocket(url);
 67→
 68→    this.ws.onopen = () => {
 69→      this.currentDelay = this.reconnectDelay;
 70→      this.onStatus("connected");
 71→    };
 72→
 73→    this.ws.onmessage = (evt) => {
 74→      try {
 75→        const data = JSON.parse(evt.data);
 76→        this.onMessage(data);
 77→      } catch (e) {
 78→        console.error("[SUPER DUPER] Bad message:", evt.data);
 79→      }
 80→    };
 81→
 82→    this.ws.onclose = () => {
 83→      this.onStatus("disconnected");
 84→      if (!this._closed) {
 85→        setTimeout(() => this.connect(), this.currentDelay);
 86→        this.currentDelay = Math.min(this.currentDelay * 1.5, this.maxReconnectDelay);
 87→      }
 88→    };
 89→
 90→    this.ws.onerror = (err) => {
 91→      console.error("[SUPER DUPER] WebSocket error:", err);
 92→    };
 93→  }
 94→
 95→  send(type, payload) {
 96→    if (this.ws && this.ws.readyState === WebSocket.OPEN) {
 97→      this.ws.send(JSON.stringify({ type, ...payload }));
 98→      return true;
 99→    }
100→    return false;
101→  }
102→
103→  close() {
104→    this._closed = true;
105→    if (this.ws) this.ws.close();
106→  }
107→}
108→
109→/* ── Readability Controls ─────────────────────────────────────────── */
110→
111→const SVG_NS = "http://www.w3.org/2000/svg";
112→const FONT_STEPS = ["s", "m", "l"];
113→const ALIGN_OPTIONS = ["left", "center", "right"];
114→const MODE_OPTIONS = ["comfort", "compact"];
115→
116→/** Create a tiny SVG with horizontal line rects. */
117→function _svgLines(lineData) {
118→  const svg = document.createElementNS(SVG_NS, "svg");
119→  svg.setAttribute("width", "14");
120→  svg.setAttribute("height", "14");
121→  svg.setAttribute("viewBox", "0 0 14 14");
122→  for (const d of lineData) {
123→    const rect = document.createElementNS(SVG_NS, "rect");
124→    rect.setAttribute("x", String(d.x));
125→    rect.setAttribute("y", String(d.y));
126→    rect.setAttribute("width", String(d.w));
127→    rect.setAttribute("height", "1.5");
128→    rect.setAttribute("rx", "0.75");
129→    rect.setAttribute("fill", "currentColor");
130→    svg.appendChild(rect);
131→  }
132→  return svg;
133→}
134→
135→/** Alignment icon — three lines with position weight. */
136→function _alignIcon(align) {
137→  const specs = {
138→    left:   [{ x: 1, y: 3, w: 12 }, { x: 1, y: 6.5, w: 8 },  { x: 1, y: 10, w: 10 }],
139→    center: [{ x: 1, y: 3, w: 12 }, { x: 3, y: 6.5, w: 8 },  { x: 2, y: 10, w: 10 }],
140→    right:  [{ x: 1, y: 3, w: 12 }, { x: 5, y: 6.5, w: 8 },  { x: 3, y: 10, w: 10 }],
141→  };
142→  return _svgLines(specs[align]);
143→}
144→
145→/** Mode icon — three lines with gap spacing. */
146→function _modeIcon(mode) {
147→  const ys = mode === "comfort" ? [2, 6.25, 10.5] : [4, 6.25, 8.5];
148→  return _svgLines(ys.map(y => ({ x: 2, y, w: 10 })));
149→}
150→
151→/** Create a readbar button. */
152→function _readBtn(title, ariaLabel) {
153→  const btn = document.createElement("button");
154→  btn.className = "sd-readbar__btn";
155→  btn.title = title;
156→  btn.setAttribute("aria-label", ariaLabel || title);
157→  return btn;
158→}
159→
160→/** Create a separator. */
161→function _readSep() {
162→  const sep = document.createElement("span");
163→  sep.className = "sd-readbar__sep";
164→  return sep;
165→}
166→
167→/** Populate the readability bar. */
168→function _buildReadbar(barEl, messagesEl) {
169→  // Restore saved preferences (comfort + m + left are defaults)
170→  const savedFont  = localStorage.getItem("sd-font")  || "m";
171→  const savedAlign = localStorage.getItem("sd-align") || "left";
172→  const savedMode  = localStorage.getItem("sd-mode")  || "comfort";
