250→function buildSidebar(el) {
251→  el.style.height = "100%";
252→  el.style.display = "flex";
253→  el.style.flexDirection = "column";
254→
255→  el.innerHTML = `
256→    <div class="sd-header">
257→      <span class="sd-header__title">${SIDEBAR_TITLE}</span>
258→      <span class="sd-header__status" id="sd-status"></span>
