/* ── Dispatch Card (Agent Deployment) ────────────────────────────── */

@keyframes sd-dispatch-enter {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.sd-dispatch-card {
  background: #16162a;
  border: 1px solid #ffffff08;
  border-radius: 10px;
  padding: var(--space-lg);
  margin: var(--space-md) 0;
  animation: sd-dispatch-enter var(--duration-med) var(--ease-out-expo) both;
}

.sd-dispatch__header {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  font-weight: 400;
  color: #888;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-md);
}

.sd-dispatch__prompt {
  font-family: "IBM Plex Sans", var(--sd-font-sans);
  font-size: 13px;
  font-style: italic;
  color: var(--sd-text-secondary);
  line-height: 1.65;
  border-left: 2px solid var(--sd-accent);
  padding: var(--space-xs) var(--space-md);
  margin-bottom: var(--space-lg);
}

.sd-dispatch__rows {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sd-dispatch__row {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border-radius: 6px;
  transition: background var(--duration-fast) ease;
}

.sd-dispatch__row:hover {
  background: #ffffff06;
}

.sd-dispatch__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.sd-dispatch__name {
  font-family: var(--sd-font-mono);
  font-size: 12px;
  font-weight: 700;
  color: var(--sd-text-primary);
  letter-spacing: 0.02em;
  min-width: 90px;
}

.sd-dispatch__role {
  font-family: "IBM Plex Sans", var(--sd-font-sans);
  font-size: 11px;
  color: var(--sd-text-muted);
  line-height: 1.65;
  flex: 1;
}

.sd-dispatch__status-area {
  margin-left: auto;
  flex-shrink: 0;
}

.sd-dispatch__status {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  letter-spacing: 0.01em;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sd-dispatch__status--waiting {
  color: var(--sd-text-muted);
}

.sd-dispatch__status--active {
  color: var(--sd-accent);
}

.sd-dispatch__status--complete {
  color: #81C784;
}

.sd-dispatch__status--error {
  color: #FF6E6E;
}

@keyframes sd-dispatch-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.sd-dispatch__pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--sd-accent);
  animation: sd-dispatch-pulse 1.2s ease-in-out infinite;
  flex-shrink: 0;
}

.sd-dispatch__duration {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: #555;
  margin-left: 6px;
}

.sd-dispatch__footer {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  color: var(--sd-text-muted);
  text-align: center;
  padding-top: var(--space-md);
  margin-top: var(--space-md);
  border-top: 1px solid #ffffff08;
  letter-spacing: 0.01em;
}

