  font-style: italic;
  color: var(--sd-text-secondary);
  line-height: 1.65;
  border-left: 2px solid var(--sd-accent);
  padding: var(--space-xs) var(--space-md);
  margin-bottom: var(--space-lg);
}

.sd-dispatch__rows {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sd-dispatch__row {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border-radius: 6px;
  transition: background var(--duration-fast) ease;
}

.sd-dispatch__row:hover {
  background: #ffffff06;
}

.sd-dispatch__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
