248→/* ── Build the sidebar DOM ────────────────────────────────────────── */
249→
250→function buildSidebar(el) {
251→  el.style.height = "100%";
252→  el.style.display = "flex";
253→  el.style.flexDirection = "column";
254→
255→  el.innerHTML = `
256→    <div class="sd-header">
257→      <span class="sd-header__title">${SIDEBAR_TITLE}</span>
258→      <span class="sd-header__status" id="sd-status"></span>
259→    </div>
260→    <div class="sd-stage-bar" id="sd-stage" style="display:none">
261→      <span class="sd-stage__label" id="sd-stage-label"></span>
262→      <span class="sd-stage__detail" id="sd-stage-detail"></span>
263→    </div>
264→    <div class="sd-messages" id="sd-messages" role="log" aria-live="polite" aria-label="Chat with Super Duper AI">
265→      <div class="sd-message sd-message--system">
266→        <span class="sd-message__body">What would you like to do with your workflow?</span>
267→      </div>
268→    </div>
269→    <div class="sd-readbar" id="sd-readbar"></div>
270→    <div class="sd-input-bar">
271→      <input
272→        type="text"
273→        id="sd-input"
274→        class="sd-input"
275→        placeholder="Ask me anything about your workflow..."
276→        autocomplete="off"
277→      />
278→      <button id="sd-send" class="sd-send-btn" aria-label="Send message">Send</button>
279→    </div>
280→  `;
281→
282→  const messagesEl = el.querySelector("#sd-messages");
283→  const inputEl = el.querySelector("#sd-input");
284→  const sendBtn = el.querySelector("#sd-send");
285→  const statusEl = el.querySelector("#sd-status");
286→  const stageBar = el.querySelector("#sd-stage");
287→  const stageLabel = el.querySelector("#sd-stage-label");
288→  const stageDetail = el.querySelector("#sd-stage-detail");
289→  const readbarEl = el.querySelector("#sd-readbar");
290→
291→  // Build readability controls
292→  _buildReadbar(readbarEl, messagesEl);
293→
294→  let busy = false;
295→  let streamingEl = null;     // element receiving streamed text deltas
296→  let streamAccum = "";       // accumulated text during streaming
297→  let typingIndicator = null; // typing dots shown during stream
298→
299→  function scrollToBottom() {
300→    messagesEl.scrollTop = messagesEl.scrollHeight;
301→  }
302→
303→  function setStage(stage, detail, nodesTouched) {
304→    if (stage === "DONE" || !stage) {
305→      stageBar.style.display = "none";
306→      return;
307→    }
308→    stageBar.style.display = "flex";
309→    stageLabel.textContent = stage;
310→    stageDetail.textContent = detail || "";
311→
312→    // Remove existing pills
313→    const existingPills = stageBar.querySelectorAll(".sd-node-pill");
314→    existingPills.forEach(p => p.remove());
315→
316→    // Render node pills if provided
317→    if (nodesTouched && nodesTouched.length > 0) {
318→      for (const node of nodesTouched) {
319→        const pill = createNodePill(
320→          node.class_type,
321→          node.slot_type,
322→          node.node_id
323→        );
324→        stageBar.appendChild(pill);
325→      }
326→    }
327→  }
328→
329→  function setBusy(state) {
330→    busy = state;
331→    sendBtn.disabled = state;
332→    inputEl.disabled = state;
333→    sendBtn.textContent = state ? "..." : "Send";
334→  }
335→
336→  /* ── WebSocket message handler ────────────────────────────────── */
337→
338→  function handleAgentMessage(data) {
339→    switch (data.type) {
340→      case "connected":
341→        break;
342→
343→      case "text_delta":
344→        // Streaming: show typing indicator, accumulate text
345→        if (!streamingEl) {
346→          streamingEl = document.createElement("div");
347→          streamingEl.className = "sd-message sd-message--agent";
348→
349→          const label = document.createElement("span");
350→          label.className = "sd-message__label";
351→          label.textContent = "Agent";
352→          streamingEl.appendChild(label);
353→
354→          const body = document.createElement("div");
355→          body.className = "sd-message__body sd-text-body";
356→          streamingEl.appendChild(body);
357→
358→          messagesEl.appendChild(streamingEl);
359→          streamAccum = "";
360→        }
361→
362→        streamAccum += data.text;
363→
364→        // Show typing indicator during streaming
365→        const streamBody = streamingEl.querySelector(".sd-message__body");
366→        if (!typingIndicator) {
367→          typingIndicator = createTypingIndicator();
368→          streamBody.appendChild(typingIndicator);
369→        }
370→
371→        scrollToBottom();
372→        break;
373→
374→      case "message": {
375→        // Full message — render with rich text, replacing streaming element
376→        const finalText = data.content || streamAccum;
377→
378→        if (streamingEl) {
379→          // Replace streaming content with final rendered text
380→          const body = streamingEl.querySelector(".sd-message__body");
381→          body.textContent = ""; // clear typing indicator
382→          body.classList.add("sd-text-body");
383→          body.appendChild(renderText(finalText));
384→          streamingEl = null;
385→          streamAccum = "";
386→          typingIndicator = null;
387→        } else {
388→          messagesEl.appendChild(createMessageEl("agent", finalText));
389→        }
390→        scrollToBottom();
391→        break;
392→      }
393→
394→      case "panel": {
395→        // Structured panel from tool result
396→        const panelEl = createPanel(data.panel);
397→        if (panelEl) {
398→          // Wrap in a message container for consistent spacing
399→          const wrapper = document.createElement("div");
400→          wrapper.className = "sd-message sd-message--agent";
401→          wrapper.style.padding = "0";
402→          wrapper.style.background = "none";
403→          wrapper.appendChild(panelEl);
404→          messagesEl.appendChild(wrapper);
405→          scrollToBottom();
406→        }
407→        break;
408→      }
409→
410→      case "stage":
411→        setStage(data.stage, data.detail, data.nodes_touched);
412→
413→        // Show node interaction indicator in chat
414→        if (data.nodes_touched && data.nodes_touched.length > 0 && data.stage !== "DONE") {
415→          const nodeMsg = document.createElement("div");
416→          nodeMsg.className = "sd-message sd-message--node-activity";
417→
418→          const activityLabel = document.createElement("span");
419→          activityLabel.className = "sd-node-activity__label";
420→          activityLabel.textContent = data.stage === "PILOT" ? "Modifying" : "Inspecting";
421→          nodeMsg.appendChild(activityLabel);
422→
423→          for (const node of data.nodes_touched) {
424→            const pill = createNodePill(
425→              node.class_type,
426→              node.slot_type,
427→              node.node_id
428→            );
429→            nodeMsg.appendChild(pill);
430→          }
431→
432→          messagesEl.appendChild(nodeMsg);
433→          scrollToBottom();
434→        }
435→
436→        if (data.stage === "DONE") {
437→          // Clean up streaming state
438→          if (streamingEl && streamAccum) {
439→            const body = streamingEl.querySelector(".sd-message__body");
440→            body.textContent = "";
441→            body.classList.add("sd-text-body");
442→            body.appendChild(renderText(streamAccum));
443→          }
444→          streamingEl = null;
445→          streamAccum = "";
446→          typingIndicator = null;
447→          setBusy(false);
448→        }
449→        break;
450→
