  break;

case "agent_dispatch": {
  // Insert dispatch card ABOVE upcoming chat messages
  const cardData = {
    prompt: data.prompt,
    agents: data.agents || [],
    estimate: data.estimate_seconds != null ? `~${data.estimate_seconds}s` : undefined,
    nodeCount: data.node_count,
  };
