  if (dispatchCard) {
    updateAgentStatus(
      dispatchCard,
      data.agent_key,
      data.status,
      data.message,
      data.duration
    );
    scrollToBottom();
  }
  break;

case "error":
  setStage(null);
  messagesEl.appendChild(createMessageEl("system", data.message));
  streamingEl = null;
  streamAccum = "";
  typingIndicator = null;
  setBusy(false);
  scrollToBottom();
