  if (role === "agent") {
    // Rich text rendering for agent messages
    body.classList.add("sd-text-body");
    body.appendChild(renderText(text));
  } else {
    // Plain text for user and system messages
    body.textContent = text;
  }

  msg.appendChild(body);
  return msg;
}

