 6→/* ── SUPER DUPER Sidebar ─────────────────────────────────────────────
 7→ *  Registers a sidebar tab in ComfyUI's extension manager.
 8→ *  Chat interface with WebSocket connection to agent brain.
 9→ * ──────────────────────────────────────────────────────────────────── */
10→
11→const SIDEBAR_ID = "superduper";
12→const SIDEBAR_TITLE = "Super Duper";
13→
14→/* ── Load stylesheet ──────────────────────────────────────────────── */
15→
