23→function createMessageEl(role, text) {
24→  const msg = document.createElement("div");
25→  msg.className = `sd-message sd-message--${role}`;
26→
27→  if (role !== "system") {
28→    const label = document.createElement("span");
29→    label.className = "sd-message__label";
30→    label.textContent = role === "user" ? "You" : "Agent";
31→    msg.appendChild(label);
32→  }
33→
34→  const body = document.createElement("div");
35→  body.className = "sd-message__body";
36→
37→  if (role === "agent") {
38→    // Rich text rendering for agent messages
39→    body.classList.add("sd-text-body");
40→    body.appendChild(renderText(text));
41→  } else {
42→    // Plain text for user and system messages
43→    body.textContent = text;
44→  }
45→
46→  msg.appendChild(body);
47→  return msg;
48→}
49→
50→/* ── WebSocket connection ─────────────────────────────────────────── */
51→
52→class AgentConnection {
53→  constructor(onMessage, onStatus) {
54→    this.ws = null;
55→    this.onMessage = onMessage;   // (event) => void
56→    this.onStatus = onStatus;     // (status) => void
57→    this.reconnectDelay = 1000;
58→    this.maxReconnectDelay = 15000;
59→    this.currentDelay = this.reconnectDelay;
60→    this._closed = false;
61→  }
62→
63→  connect() {
64→    const proto = location.protocol === "https:" ? "wss:" : "ws:";
65→    const url = `${proto}//${location.host}/superduper/ws`;
66→
67→    this.onStatus("connecting");
68→    this.ws = new WebSocket(url);
69→
70→    this.ws.onopen = () => {
71→      this.currentDelay = this.reconnectDelay;
72→      this.onStatus("connected");
73→    };
74→
75→    this.ws.onmessage = (evt) => {
76→      try {
77→        const data = JSON.parse(evt.data);
