/** Create a readbar button. */
function _readBtn(title, ariaLabel) {
  const btn = document.createElement("button");
  btn.className = "sd-readbar__btn";
  btn.title = title;
  btn.setAttribute("aria-label", ariaLabel || title);
  return btn;
}

/** Create a separator. */
function _readSep() {
  const sep = document.createElement("span");
  sep.className = "sd-readbar__sep";
  return sep;
}

/** Populate the readability bar. */
function _buildReadbar(barEl, messagesEl) {
  // Restore saved preferences (comfort + m + left are defaults)
  const savedFont  = localStorage.getItem("sd-font")  || "m";
  const savedAlign = localStorage.getItem("sd-align") || "left";
  const savedMode  = localStorage.getItem("sd-mode")  || "comfort";

  messagesEl.dataset.font  = savedFont;
  messagesEl.dataset.align = savedAlign;
  messagesEl.dataset.mode  = savedMode;

  // ── Font size: A↓ A↑ ──
  const fontDown = _readBtn("Smaller text");
  fontDown.classList.add("sd-readbar__btn--font-down");
  fontDown.textContent = "A";
  fontDown.addEventListener("click", () => {
    const i = FONT_STEPS.indexOf(messagesEl.dataset.font);
    if (i > 0) {
      messagesEl.dataset.font = FONT_STEPS[i - 1];
      localStorage.setItem("sd-font", messagesEl.dataset.font);
    }
  });
  barEl.appendChild(fontDown);

  const fontUp = _readBtn("Larger text");
  fontUp.classList.add("sd-readbar__btn--font-up");
  fontUp.textContent = "A";
  fontUp.addEventListener("click", () => {
    const i = FONT_STEPS.indexOf(messagesEl.dataset.font);
    if (i < FONT_STEPS.length - 1) {
      messagesEl.dataset.font = FONT_STEPS[i + 1];
      localStorage.setItem("sd-font", messagesEl.dataset.font);
    }
  });
  barEl.appendChild(fontUp);

  barEl.appendChild(_readSep());

  // ── Alignment: left / center / right ──
  const alignBtns = {};
  for (const align of ALIGN_OPTIONS) {
    const btn = _readBtn(`${align.charAt(0).toUpperCase() + align.slice(1)} align`);
    btn.appendChild(_alignIcon(align));
    btn.addEventListener("click", () => {
      messagesEl.dataset.align = align;
      localStorage.setItem("sd-align", align);
      _syncActive();
    });
    alignBtns[align] = btn;
    barEl.appendChild(btn);
  }

  barEl.appendChild(_readSep());

  // ── Mode: comfort / compact ──
  const modeBtns = {};
  const modeLabels = { comfort: "Comfort reading", compact: "Compact reading" };
  for (const mode of MODE_OPTIONS) {
    const btn = _readBtn(modeLabels[mode]);
    btn.appendChild(_modeIcon(mode));
    btn.addEventListener("click", () => {
      messagesEl.dataset.mode = mode;
      localStorage.setItem("sd-mode", mode);
      _syncActive();
    });
    modeBtns[mode] = btn;
    barEl.appendChild(btn);
  }

  // Sync active highlights
  function _syncActive() {
    for (const [k, b] of Object.entries(alignBtns)) {
      b.classList.toggle("sd-readbar__btn--active", k === messagesEl.dataset.align);
    }
    for (const [k, b] of Object.entries(modeBtns)) {
      b.classList.toggle("sd-readbar__btn--active", k === messagesEl.dataset.mode);
    }
  }
  _syncActive();
}

/* ── Build the sidebar DOM ────────────────────────────────────────── */

function buildSidebar(el) {
  el.style.height = "100%";
  el.style.display = "flex";
  el.style.flexDirection = "column";

  el.innerHTML = `
    <div class="sd-header">
      <span class="sd-header__title">${SIDEBAR_TITLE}</span>
      <span class="sd-header__status" id="sd-status"></span>
    </div>
    <div class="sd-stage-bar" id="sd-stage" style="display:none">
      <span class="sd-stage__label" id="sd-stage-label"></span>
      <span class="sd-stage__detail" id="sd-stage-detail"></span>
    </div>
    <div class="sd-messages" id="sd-messages" role="log" aria-live="polite" aria-label="Chat with Super Duper AI">
      <div class="sd-message sd-message--system">
        <span class="sd-message__body">What would you like to do with your workflow?</span>
      </div>
    </div>
    <div class="sd-readbar" id="sd-readbar"></div>
    <div class="sd-input-bar">
      <input
        type="text"
        id="sd-input"
        class="sd-input"
        placeholder="Ask me anything about your workflow..."
        autocomplete="off"
      />
      <button id="sd-send" class="sd-send-btn" aria-label="Send message">Send</button>
    </div>
  `;

  const messagesEl = el.querySelector("#sd-messages");
  const inputEl = el.querySelector("#sd-input");
  const sendBtn = el.querySelector("#sd-send");
  const statusEl = el.querySelector("#sd-status");
  const stageBar = el.querySelector("#sd-stage");
  const stageLabel = el.querySelector("#sd-stage-label");
  const stageDetail = el.querySelector("#sd-stage-detail");
  const readbarEl = el.querySelector("#sd-readbar");

  // Build readability controls
  _buildReadbar(readbarEl, messagesEl);

  let busy = false;
  let streamingEl = null;     // element receiving streamed text deltas
  let streamAccum = "";       // accumulated text during streaming
  let typingIndicator = null; // typing dots shown during stream
  let dispatchCard = null;    // current agent dispatch card element
  let progressPanel = null;   // current progress panel element
  let pipelineState = {};     // tracks pipeline stage statuses

  function scrollToBottom() {
    messagesEl.scrollTop = messagesEl.scrollHeight;
  }

  function setStage(stage, detail, nodesTouched) {
    if (stage === "DONE" || !stage) {
      stageBar.style.display = "none";
      return;
    }
    stageBar.style.display = "flex";
    stageLabel.textContent = stage;
    stageDetail.textContent = detail || "";

    // Remove existing pills
    const existingPills = stageBar.querySelectorAll(".sd-node-pill");
    existingPills.forEach(p => p.remove());

    // Render node pills if provided
    if (nodesTouched && nodesTouched.length > 0) {
      for (const node of nodesTouched) {
        const pill = createNodePill(
          node.class_type,
          node.slot_type,
          node.node_id
        );
        stageBar.appendChild(pill);
      }
    }
  }

  function setBusy(state) {
    busy = state;
    sendBtn.disabled = state;
    inputEl.disabled = state;
    sendBtn.textContent = state ? "..." : "Send";
  }

  /* ── WebSocket message handler ────────────────────────────────── */

  function handleAgentMessage(data) {
    switch (data.type) {
      case "connected":
        break;

      case "text_delta":
        _clearThinking();
        // Streaming: show typing indicator, accumulate text
        if (!streamingEl) {
          streamingEl = document.createElement("div");
          streamingEl.className = "sd-message sd-message--agent";

          const label = document.createElement("span");
          label.className = "sd-message__label";
          label.textContent = "Agent";
          streamingEl.appendChild(label);

          const body = document.createElement("div");
          body.className = "sd-message__body sd-text-body";
          streamingEl.appendChild(body);

          messagesEl.appendChild(streamingEl);
          streamAccum = "";
        }

        streamAccum += data.text;

        // Show typing indicator during streaming
        const streamBody = streamingEl.querySelector(".sd-message__body");
        if (!typingIndicator) {
          typingIndicator = createTypingIndicator();
          streamBody.appendChild(typingIndicator);
        }

        scrollToBottom();
        break;

      case "message": {
        // Full message — render with rich text, replacing streaming element
        const finalText = data.content || streamAccum;

        if (streamingEl) {
          // Replace streaming content with final rendered text
          const body = streamingEl.querySelector(".sd-message__body");
          body.textContent = ""; // clear typing indicator
          body.classList.add("sd-text-body");
          body.appendChild(renderText(finalText));
          streamingEl = null;
          streamAccum = "";
          typingIndicator = null;
        } else {
          messagesEl.appendChild(createMessageEl("agent", finalText));
        }
        scrollToBottom();
        break;
      }

      case "panel": {
        // Structured panel from tool result
        const panelEl = createPanel(data.panel);
        if (panelEl) {
          // Wrap in a message container for consistent spacing
          const wrapper = document.createElement("div");
          wrapper.className = "sd-message sd-message--agent";
          wrapper.style.padding = "0";
          wrapper.style.background = "none";
          wrapper.appendChild(panelEl);
          messagesEl.appendChild(wrapper);
          scrollToBottom();
        }
        break;
      }

      case "stage":
        _clearThinking();
        setStage(data.stage, data.detail, data.nodes_touched);

        // Show node interaction indicator in chat
        if (data.nodes_touched && data.nodes_touched.length > 0 && data.stage !== "DONE") {
          const nodeMsg = document.createElement("div");
          nodeMsg.className = "sd-message sd-message--node-activity";

          const activityLabel = document.createElement("span");
          activityLabel.className = "sd-node-activity__label";
          activityLabel.textContent = data.stage === "PILOT" ? "Modifying" : "Inspecting";
          nodeMsg.appendChild(activityLabel);

          for (const node of data.nodes_touched) {
            const pill = createNodePill(
              node.class_type,
              node.slot_type,
              node.node_id
            );
            nodeMsg.appendChild(pill);
          }

          messagesEl.appendChild(nodeMsg);
          scrollToBottom();
        }

        if (data.stage === "DONE") {
          // Clean up streaming state
          if (streamingEl && streamAccum) {
            const body = streamingEl.querySelector(".sd-message__body");
            body.textContent = "";
            body.classList.add("sd-text-body");
            body.appendChild(renderText(streamAccum));
          }
          streamingEl = null;
          streamAccum = "";
          typingIndicator = null;
          dispatchCard = null;
          if (progressPanel) {
            progressPanel.remove();
            progressPanel = null;
          }
          pipelineState = {};
          setBusy(false);
        }
        break;

      case "progress":
        // ComfyUI execution progress — update bar and node detail
        if (progressPanel) {
          updateProgress(progressPanel, {
            progress: data.progress != null ? data.progress : null,
            currentNode: data.current_node || data.currentNode,
            nodeIndex: data.node_index != null ? data.node_index : data.nodeIndex,
            nodeTotal: data.node_total != null ? data.node_total : data.nodeTotal,
            etaSeconds: data.eta_seconds != null ? data.eta_seconds : data.etaSeconds,
          });
          scrollToBottom();
        }
        break;

      case "agent_dispatch": {
        // Insert dispatch card ABOVE upcoming chat messages
        const cardData = {
          prompt: data.prompt,
          agents: data.agents || [],
          estimate: data.estimate_seconds != null ? `~${data.estimate_seconds}s` : undefined,
          nodeCount: data.node_count,
        };
        dispatchCard = createDispatchCard(cardData);
        messagesEl.appendChild(dispatchCard);

        // Create progress panel below the dispatch card
        pipelineState = { router: "waiting", intent: "waiting", execution: "waiting", verify: "waiting" };
        progressPanel = createProgressPanel();
        messagesEl.appendChild(progressPanel);

        scrollToBottom();
        break;
      }

      case "agent_status":
        if (dispatchCard) {
          updateAgentStatus(
            dispatchCard,
            data.agent_key,
            data.status,
            data.message,
            data.duration
          );
        }
        // Update pipeline level in progress panel
        if (progressPanel && data.agent_key in pipelineState) {
          pipelineState[data.agent_key] = data.status;
          updateProgress(progressPanel, { pipeline: pipelineState });
        }
        scrollToBottom();
        break;

      case "error":
        setStage(null);
        messagesEl.appendChild(createMessageEl("system", data.message));
        streamingEl = null;
        streamAccum = "";
        typingIndicator = null;
        setBusy(false);
        scrollToBottom();
        break;

      default:
        console.log("[SUPER DUPER] Unknown event:", data);
    }
  }

  function handleStatus(status) {
    statusEl.textContent = status === "connected" ? "" : status;
    statusEl.className = `sd-header__status sd-header__status--${status}`;
  }

  /* ── Connect ──────────────────────────────────────────────────── */

  const conn = new AgentConnection(handleAgentMessage, handleStatus);
  conn.connect();

  /* ── Send message ─────────────────────────────────────────────── */

  function _showThinking() {
    const el = document.createElement("div");
    el.className = "sd-thinking";

    const dot = document.createElement("span");
    dot.className = "sd-thinking__dot";
    el.appendChild(dot);

    const label = document.createElement("span");
    label.textContent = "Connecting to agents...";
    el.appendChild(label);

    messagesEl.appendChild(el);
    scrollToBottom();
  }

  function _clearThinking() {
    const el = messagesEl.querySelector(".sd-thinking");
    if (el) el.remove();
  }

  async function sendMessage() {
    const text = inputEl.value.trim();
    if (!text || busy) return;

    // Show user message immediately
    messagesEl.appendChild(createMessageEl("user", text));
    inputEl.value = "";

    // Show thinking indicator right away
    _showThinking();
    scrollToBottom();

    // Capture current workflow from ComfyUI canvas
    let workflow = null;
    try {
      const result = await app.graphToPrompt();
      if (result && result.output) {
        workflow = result.output;
      }
    } catch (e) {
      console.warn("[SUPER DUPER] Could not capture workflow:", e);
    }

    // Send to agent via WebSocket (include workflow if captured)
    const payload = { content: text };
    if (workflow) {
      payload.workflow = workflow;
    }
    const sent = conn.send("chat", payload);
    if (!sent) {
      _clearThinking();
      messagesEl.appendChild(
        createMessageEl("system", "Not connected. Reconnecting...")
      );
      scrollToBottom();
      return;
    }

    setBusy(true);
  }

  sendBtn.addEventListener("click", sendMessage);

  // Node pill canvas interaction (event delegation)
  messagesEl.addEventListener("click", (e) => {
    const pill = e.target.closest(".sd-node-pill");
    if (!pill || !pill.dataset.nodeId) return;

    try {
      const graph = app.graph;
      if (graph) {
        const node = graph.getNodeById(parseInt(pill.dataset.nodeId, 10));
        if (node) {
          app.canvas.deselectAllNodes();
          app.canvas.selectNode(node);
          app.canvas.centerOnNode(node);
        }
      }
    } catch (err) {
      console.warn("[Super Duper] Could not highlight node:", err);
    }
  });

  // Node pill hover highlighting
  messagesEl.addEventListener("mouseenter", (e) => {
    const pill = e.target.closest(".sd-node-pill");
    if (!pill || !pill.dataset.nodeId) return;

    try {
      const graph = app.graph;
      if (graph) {
        const node = graph.getNodeById(parseInt(pill.dataset.nodeId, 10));
        if (node) {
          node._sd_orig_color = node.color;
          const color = getComputedStyle(pill).getPropertyValue("--pill-color").trim();
          node.color = color;
          app.canvas.setDirty(true, true);
        }
      }
    } catch (err) { /* silent */ }
  }, true);

  messagesEl.addEventListener("mouseleave", (e) => {
    const pill = e.target.closest(".sd-node-pill");
    if (!pill || !pill.dataset.nodeId) return;

    try {
      const graph = app.graph;
      if (graph) {
        const node = graph.getNodeById(parseInt(pill.dataset.nodeId, 10));
        if (node && node._sd_orig_color !== undefined) {
          node.color = node._sd_orig_color;
          delete node._sd_orig_color;
          app.canvas.setDirty(true, true);
        }
      }
    } catch (err) { /* silent */ }
  }, true);

  inputEl.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
      e.preventDefault();
      sendMessage();
    }
  });

  setTimeout(() => inputEl.focus(), 100);
}

/* ── Register with ComfyUI ────────────────────────────────────────── */

app.extensionManager.registerSidebarTab({
  id: SIDEBAR_ID,
  icon: "pi pi-bolt",
  title: SIDEBAR_TITLE,
  tooltip: "Super Duper AI Co-pilot",
  type: "custom",
  render(el) {
    buildSidebar(el);
  },
});

/* ── SUPER DUPER Design System ──────────────────────────────────────
 *  Native skin: ComfyUI dark theme palette
 *  Accent: #4e9bcd (ComfyUI native blue)
 *  Surfaces: neutral grey depth layers
 *  Typography: Inter (sans) + JetBrains Mono (mono)
 *  Slot colors: official ComfyUI dark theme
 * ──────────────────────────────────────────────────────────────────── */

@import url("https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap");

/* ── Design Tokens ──────────────────────────────────────────────── */

:root {
  /* ComfyUI Native Surfaces */
  --sd-canvas: #1e1e1e;
  --sd-panel: #2b2b2b;
  --sd-card: #353535;
  --sd-card-hover: #3a3a3a;
  --sd-elevated: #404040;
  --sd-input: #1a1a1a;

  /* ComfyUI Native Text */
  --sd-text-primary: #ddd;
  --sd-text-secondary: #aaa;
  --sd-text-muted: #888;
  --sd-text-accent: #ccc;

  /* ComfyUI Native Borders */
  --sd-border: #4e4e4e;
  --sd-border-subtle: #3a3a3a;

  /* Accent (ComfyUI native blue -- replaces jade green) */
  --sd-accent: #4e9bcd;
  --sd-accent-dim: #4e9bcd33;
  --sd-accent-subtle: #4e9bcd18;

  /* Keep ALL slot colors unchanged */
  --sd-slot-clip: #FFD500;
  --sd-slot-clip-vision: #A8DADC;
  --sd-slot-conditioning: #FFA931;
  --sd-slot-controlnet: #6EE7B7;
  --sd-slot-image: #64B5F6;
  --sd-slot-latent: #FF9CF9;
  --sd-slot-mask: #81C784;
  --sd-slot-model: #B39DDB;
  --sd-slot-style-model: #C2FFAE;
  --sd-slot-vae: #FF6E6E;
  --sd-slot-noise: #B0B0B0;
  --sd-slot-guider: #66FFFF;
  --sd-slot-sampler: #ECB4B4;
  --sd-slot-sigmas: #CDFFCD;

  /* Agent Identity Colors */
  --agent-router: #00BB81;
  --agent-intent: #FFD500;
  --agent-execution: #64B5F6;
  --agent-verify: #FF6E6E;
  --agent-doctor: #B39DDB;

  /* Typography */
  --sd-font-sans: "Inter", "SF Pro Display", system-ui, -apple-system, sans-serif;
  --sd-font-mono: "JetBrains Mono", "Fira Code", "SF Mono", "Cascadia Code", monospace;

  /* Spacing */
  --sd-space-xs: 4px;
  --sd-space-sm: 6px;
  --sd-space-md: 8px;
  --sd-space-lg: 12px;
  --sd-space-xl: 16px;
  --sd-space-2xl: 24px;
  --sd-space-3xl: 32px;
  --sd-msg-gap: 20px;
  --sd-para-gap: 12px;

  /* ADHD Spacing (generous, scannable) */
  --space-xs: 6px;
  --space-sm: 10px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 36px;

  /* Motion */
  --ease-out-expo: cubic-bezier(0.16, 1, 0.3, 1);
  --duration-fast: 150ms;
  --duration-med: 300ms;

  --sd-transition: 150ms ease;
}

/* ── Layout Shell ───────────────────────────────────────────────── */

.sd-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--sd-space-lg) var(--sd-space-xl);
  font-family: var(--sd-font-sans);
  font-size: 13px;
  font-weight: 500;
  letter-spacing: 0.02em;
  color: var(--sd-text-primary);
  border-bottom: 1px solid var(--sd-border-subtle);
  background: var(--sd-panel);
  flex-shrink: 0;
}

.sd-header__title {
  flex: 1;
}

.sd-header__status {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sd-header__status--connecting {
  color: #e6a23c;
}

.sd-header__status--disconnected {
  color: #f56c6c;
}

/* ── Stage Indicator ────────────────────────────────────────────── */

.sd-stage-bar {
  display: flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-xs) var(--space-md);
  background: var(--sd-accent-subtle);
  border-bottom: 1px solid var(--sd-border-subtle);
  flex-shrink: 0;
  font-size: 12px;
  animation: sd-pulse 1.5s ease-in-out infinite;
}

.sd-stage__label {
  font-family: var(--sd-font-mono);
  color: var(--sd-accent);
  font-weight: 600;
  font-size: 10px;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.sd-stage__detail {
  font-family: var(--sd-font-sans);
  color: var(--sd-text-muted);
  font-size: 11px;
}

@keyframes sd-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.6; }
}

/* ── Messages Area ──────────────────────────────────────────────── */

.sd-messages {
  flex: 1;
  overflow-y: auto;
  padding: var(--space-md) var(--space-md) var(--space-md) var(--space-md);
  padding-right: var(--space-sm);
  display: flex;
  flex-direction: column;
  gap: var(--space-md);
  background: var(--sd-canvas);
}

/* ── Message Bubbles ────────────────────────────────────────────── */

.sd-message {
  display: flex;
  flex-direction: column;
  gap: var(--sd-space-sm);
  padding: var(--space-md) var(--space-lg);
  margin-bottom: var(--space-md);
  border-radius: 8px;
  font-family: var(--sd-font-sans);
  font-size: 13px;
  line-height: 1.65;
  word-wrap: break-word;
}

.sd-message--user {
  background: var(--sd-card);
  align-self: flex-end;
  max-width: 90%;
  border: 1px solid var(--sd-border-subtle);
}

.sd-message--agent {
  background: var(--sd-panel);
  align-self: flex-start;
  max-width: 95%;
  border-left: 2px solid var(--sd-accent-dim);
}

.sd-message--system {
  background: transparent;
  color: var(--sd-text-muted);
  font-style: italic;
  font-size: 11px;
  align-self: center;
}

.sd-message__label {
  font-family: var(--sd-font-mono);
  font-size: 10.5px;
  font-weight: 400;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-bottom: 2px;
}

.sd-message--user .sd-message__label {
  color: var(--sd-text-accent);
}

.sd-message--agent .sd-message__label {
  color: var(--sd-accent);
}

.sd-message__body {
  color: var(--sd-text-secondary);
  max-width: 640px;
  letter-spacing: 0.01em;
}

.sd-message--user .sd-message__body {
  color: var(--sd-text-primary);
}

.sd-message--system .sd-message__body {
  color: var(--sd-text-muted);
}

/* Visual breathing line between consecutive agent messages */
.sd-message--agent + .sd-message--agent {
  padding-top: var(--sd-space-xl);
  border-top: 1px solid var(--sd-border-subtle);
  margin-top: var(--sd-space-xs);
}

/* ── Text Rendering Classes ─────────────────────────────────────── */

.sd-text-body {
  font-family: var(--sd-font-sans);
  font-size: 13px;
  color: var(--sd-text-secondary);
  line-height: 1.65;
  letter-spacing: 0.01em;
}

.sd-text-body p {
  margin: 0 0 var(--space-sm) 0;
}

.sd-text-body p:last-child {
  margin-bottom: 0;
}

.sd-code-inline {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  background: var(--sd-elevated);
  color: var(--sd-text-accent);
  padding: var(--space-xs) var(--space-sm);
  border-radius: 3px;
  letter-spacing: 0.01em;
}

.sd-code-block {
  font-family: var(--sd-font-mono);
  font-size: 11.5px;
  line-height: 1.65;
  background: var(--sd-input);
  color: var(--sd-text-primary);
  padding: var(--space-md);
  border-radius: 4px;
  border: 1px solid var(--sd-border-subtle);
  margin: var(--space-md) 0;
  overflow-x: auto;
  white-space: pre;
}

.sd-text-bold {
  font-weight: 600;
  color: var(--sd-text-primary);
}

/* ── Typing Indicator ───────────────────────────────────────────── */

.sd-typing {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-xs) 0;
}

.sd-typing__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--sd-accent);
  animation: sd-typing-pulse 1.2s ease-in-out infinite;
}

.sd-typing__dot:nth-child(2) {
  animation-delay: 0.15s;
}

.sd-typing__dot:nth-child(3) {
  animation-delay: 0.3s;
}

@keyframes sd-typing-pulse {
  0%, 60%, 100% { opacity: 0.3; transform: scale(0.8); }
  30% { opacity: 1; transform: scale(1); }
}

/* ── Input Bar ──────────────────────────────────────────────────── */

.sd-input-bar {
  display: flex;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-md);
  margin-top: var(--space-md);
  border-top: 1px solid var(--sd-border);
  background: var(--sd-panel);
  flex-shrink: 0;
}

.sd-input {
  flex: 1;
  background: var(--sd-input);
  border: 1px solid var(--sd-border);
  border-radius: 6px;
  padding: var(--space-sm) var(--space-md);
  color: var(--sd-text-primary);
  font-family: var(--sd-font-sans);
  font-size: 12px;
  outline: none;
  transition: border-color var(--sd-transition);
}

.sd-input:focus {
  border-color: var(--sd-accent);
}

.sd-input::placeholder {
  color: var(--sd-text-muted);
}

.sd-send-btn {
  background: var(--sd-accent);
  color: #1a1a1a;
  border: none;
  border-radius: 6px;
  padding: var(--space-sm) var(--space-md);
  font-family: var(--sd-font-sans);
  font-size: 12px;
  font-weight: 600;
  cursor: pointer;
  transition: background var(--sd-transition), opacity var(--sd-transition);
  flex-shrink: 0;
}

.sd-send-btn:hover {
  opacity: 0.9;
}

.sd-send-btn:active {
  opacity: 0.8;
}

.sd-send-btn:disabled {
  background: var(--sd-elevated);
  color: var(--sd-text-muted);
  cursor: not-allowed;
  opacity: 1;
}

/* ── Scrollbar ──────────────────────────────────────────────────── */

.sd-messages::-webkit-scrollbar {
  width: 3px;
}

.sd-messages::-webkit-scrollbar-track {
  background: transparent;
}

.sd-messages::-webkit-scrollbar-thumb {
  background: var(--sd-border);
  border-radius: 2px;
}

.sd-messages::-webkit-scrollbar-thumb:hover {
  background: var(--sd-text-muted);
}

/* ── Panel Components ───────────────────────────────────────────── */

/* Panel container */
.sd-panel {
  background: var(--sd-panel);
  border-radius: 6px;
  border: 1px solid var(--sd-border-subtle);
  overflow: hidden;
  margin: var(--space-sm) 0;
  max-width: 100%;
}

/* Panel header */
.sd-panel__header {
  padding: var(--space-md);
}

.sd-panel__label-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: var(--space-sm);
}

.sd-panel__label {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.sd-panel__badge {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-accent);
  background: var(--sd-accent-subtle);
  padding: var(--space-xs) var(--space-sm);
  border-radius: 3px;
  letter-spacing: 0.01em;
}

.sd-panel__title {
  font-family: var(--sd-font-sans);
  font-size: 16px;
  font-weight: 600;
  color: var(--sd-text-primary);
  letter-spacing: -0.02em;
  margin-bottom: var(--space-xs);
  line-height: 1.3;
}

.sd-panel__summary {
  font-family: var(--sd-font-sans);
  font-size: 12px;
  font-weight: 500;
  color: var(--sd-text-accent);
  line-height: 1.65;
  margin-bottom: var(--space-md);
}

.sd-panel__stats {
  display: flex;
  gap: var(--sd-space-xl);
}

.sd-panel__stat {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.sd-panel__stat-value {
  font-family: var(--sd-font-mono);
  font-size: 14px;
  font-weight: 600;
  color: var(--sd-text-primary);
}

.sd-panel__stat-label {
  font-family: var(--sd-font-sans);
  font-size: 10px;
  color: var(--sd-text-muted);
}

/* Collapsible section */
.sd-section {
  border-top: 1px solid var(--sd-border-subtle);
}

.sd-section__trigger {
  display: flex;
  align-items: center;
  width: 100%;
  padding: var(--space-sm) var(--space-md);
  background: none;
  border: none;
  cursor: pointer;
  color: var(--sd-text-primary);
  font-family: var(--sd-font-sans);
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.01em;
  text-align: left;
  gap: var(--space-sm);
  transition: background var(--sd-transition);
}

.sd-section__trigger:hover {
  background: var(--sd-card);
}

.sd-section__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  flex-shrink: 0;
}

.sd-section__title {
  flex: 1;
}

.sd-section__count {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: var(--sd-text-muted);
  letter-spacing: 0.01em;
}

.sd-section__chevron {
  font-size: 10px;
  color: var(--sd-text-muted);
  transition: transform var(--sd-transition);
  flex-shrink: 0;
}

.sd-section--open > .sd-section__trigger .sd-section__chevron {
  transform: rotate(90deg);
}

.sd-section__body {
  padding: var(--space-sm) var(--space-md) var(--space-md);
  display: none;
}

.sd-section--open > .sd-section__body {
  display: block;
}

/* Slot tag */
.sd-slot-tag {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-xs) var(--space-sm);
  border-radius: 3px;
  font-family: var(--sd-font-mono);
  font-size: 11px;
  letter-spacing: 0.01em;
  margin: 0 var(--space-xs) var(--space-xs) 0;
}

.sd-slot-tag__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  flex-shrink: 0;
}

/* Flow chain */
.sd-flow-chain {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-xs) 0;
}

.sd-flow-chain__label {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-right: var(--sd-space-md);
  width: 100%;
  margin-bottom: var(--sd-space-xs);
}

.sd-flow-chain__node {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  padding: var(--space-xs) var(--space-sm);
  border-radius: 3px;
  letter-spacing: 0.01em;
  white-space: nowrap;
}

.sd-flow-chain__arrow {
  color: var(--sd-text-muted);
  font-size: 10px;
  padding: 0 2px;
  user-select: none;
}

/* Detail row */
.sd-detail-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
  padding: var(--space-xs) 0;
  line-height: 1.65;
}

.sd-detail-row + .sd-detail-row {
  border-top: 1px solid #ffffff06;
}

.sd-detail-row__label {
  font-family: var(--sd-font-sans);
  font-size: 11px;
  color: var(--sd-text-muted);
  white-space: nowrap;
}

.sd-detail-row__leader {
  flex: 1;
  border-bottom: 1px dotted var(--sd-border);
  min-width: 16px;
  margin-bottom: 3px;
}

.sd-detail-row__value {
  font-family: var(--sd-font-mono);
  font-size: 10.5px;
  color: var(--sd-text-secondary);
  letter-spacing: 0.01em;
  white-space: nowrap;
  text-align: right;
}

/* Capability row */
.sd-capability-row {
  display: flex;
  align-items: baseline;
  gap: var(--space-sm);
  padding: var(--space-xs) 0;
  line-height: 1.65;
}

.sd-capability-row + .sd-capability-row {
  border-top: 1px solid #ffffff06;
}

.sd-capability-row__dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  flex-shrink: 0;
  margin-top: 5px;
}

.sd-capability-row__label {
  font-family: var(--sd-font-sans);
  font-size: 11px;
  font-weight: 500;
  color: var(--sd-text-accent);
  white-space: nowrap;
}

.sd-capability-row__sep {
  flex: 1;
  border-bottom: 1px solid var(--sd-border-subtle);
  min-width: 12px;
  margin-bottom: 3px;
}

.sd-capability-row__desc {
  font-family: var(--sd-font-sans);
  font-size: 10.5px;
  color: var(--sd-text-muted);
  text-align: right;
}

/* Action footer */
.sd-panel__footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: var(--space-sm) var(--space-md);
  border-top: 1px solid var(--sd-border-subtle);
}

.sd-panel__footer-status {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: var(--sd-text-muted);
  letter-spacing: 0.01em;
}

.sd-panel__footer-actions {
  display: flex;
  gap: var(--sd-space-sm);
}

.sd-btn {
  font-family: var(--sd-font-sans);
  font-size: 11px;
  font-weight: 500;
  padding: var(--space-xs) var(--space-md);
  border-radius: 4px;
  cursor: pointer;
  transition: opacity var(--sd-transition), background var(--sd-transition);
}

.sd-btn--secondary {
  background: transparent;
  border: 1px solid var(--sd-border);
  color: var(--sd-text-secondary);
}

.sd-btn--secondary:hover {
  background: var(--sd-card);
}

.sd-btn--primary {
  background: var(--sd-accent);
  border: none;
  color: #1a1a1a;
  font-weight: 600;
}

.sd-btn--primary:hover {
  opacity: 0.9;
}

/* Slot tags container */
.sd-slot-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-xs);
  padding: var(--space-xs) 0;
}

/* ── Node Pills (inline interactive node indicators) ─────────────── */

.sd-node-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: var(--space-xs) var(--space-sm);
  border-radius: 10px;
  font-family: var(--sd-font-mono);
  font-size: 11px;
  letter-spacing: 0.01em;
  background: color-mix(in srgb, var(--pill-color) 12%, transparent);
  border: 1px solid color-mix(in srgb, var(--pill-color) 25%, transparent);
  color: var(--pill-color);
  transition: background var(--sd-transition), border-color var(--sd-transition);
  white-space: nowrap;
  margin: 0 var(--space-xs);
  vertical-align: middle;
}

.sd-node-pill:hover {
  background: color-mix(in srgb, var(--pill-color) 22%, transparent);
  border-color: color-mix(in srgb, var(--pill-color) 45%, transparent);
}

.sd-node-pill[style*="cursor: pointer"]:active {
  transform: scale(0.97);
}

.sd-node-pill__dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--pill-color);
  box-shadow: 0 0 5px color-mix(in srgb, var(--pill-color) 55%, transparent);
  flex-shrink: 0;
}

/* Node activity message (shown in chat when tools touch nodes) */
.sd-message--node-activity {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: var(--space-xs);
  padding: var(--space-xs) var(--space-md);
  background: transparent;
  font-size: 11px;
  opacity: 0.85;
}

.sd-node-activity__label {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 400;
  color: var(--sd-text-muted);
  text-transform: uppercase;
  letter-spacing: 0.06em;
  margin-right: 4px;
}

/* Node pills inside the stage bar */
.sd-stage-bar .sd-node-pill {
  font-size: 10px;
  padding: var(--space-xs) var(--space-sm);
  margin-left: var(--space-xs);
}

/* Long paragraphs get extra bottom margin for scanability */
.sd-para-long {
  margin-bottom: var(--sd-space-xl) !important;
}

/* ── Readability Controls ──────────────────────────────────────── */

.sd-readbar {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: var(--space-xs);
  padding: var(--space-xs) var(--space-md);
  background: var(--sd-panel);
  border-top: 1px solid var(--sd-border-subtle);
  flex-shrink: 0;
  opacity: 0.4;
  transition: opacity 250ms ease;
}

.sd-readbar:hover {
  opacity: 1;
}

.sd-readbar__btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 22px;
  height: 22px;
  border: none;
  background: transparent;
  color: var(--sd-text-muted);
  border-radius: 3px;
  cursor: pointer;
  padding: 0;
  transition: color var(--sd-transition), background var(--sd-transition);
}

.sd-readbar__btn:hover {
  color: var(--sd-text-primary);
  background: var(--sd-card);
}

.sd-readbar__btn--active {
  color: var(--sd-accent);
  background: var(--sd-accent-subtle);
}

.sd-readbar__btn--active:hover {
  color: var(--sd-accent);
  background: var(--sd-accent-dim);
}

.sd-readbar__btn svg {
  display: block;
}

.sd-readbar__sep {
  width: 1px;
  height: 14px;
  background: var(--sd-border-subtle);
  margin: 0 var(--space-xs);
  flex-shrink: 0;
}

/* Font size text buttons */
.sd-readbar__btn--font-down {
  font-family: var(--sd-font-sans);
  font-size: 10px;
  font-weight: 700;
}

.sd-readbar__btn--font-up {
  font-family: var(--sd-font-sans);
  font-size: 14px;
  font-weight: 700;
}

/* ── Font Size Overrides ───────────────────────────────────────── */

.sd-messages[data-font="s"] .sd-message {
  font-size: 12px;
}

.sd-messages[data-font="s"] .sd-text-body {
  font-size: 12px;
}

.sd-messages[data-font="s"] .sd-code-block {
  font-size: 10.5px;
}

/* data-font="m" is the default (13px) — no override needed */

.sd-messages[data-font="l"] .sd-message {
  font-size: 15px;
}

.sd-messages[data-font="l"] .sd-text-body {
  font-size: 15px;
}

.sd-messages[data-font="l"] .sd-code-block {
  font-size: 13px;
}

/* ── Text Alignment Overrides ──────────────────────────────────── */

/* data-align="left" is default — no override needed */

.sd-messages[data-align="center"] .sd-message__body {
  text-align: center;
}

.sd-messages[data-align="right"] .sd-message__body {
  text-align: right;
}

/* ── Compact Mode Overrides (comfort is the default base) ──────── */

.sd-messages[data-mode="compact"] {
  gap: 10px;
}

.sd-messages[data-mode="compact"] .sd-message {
  line-height: 1.45;
  padding: var(--sd-space-sm) var(--sd-space-lg);
}

.sd-messages[data-mode="compact"] .sd-text-body p {
  margin-bottom: 4px;
}

.sd-messages[data-mode="compact"] .sd-message--agent + .sd-message--agent {
  padding-top: var(--sd-space-sm);
  border-top: none;
  margin-top: 0;
}

.sd-messages[data-mode="compact"] .sd-message--agent {
  border-left-color: transparent;
}

.sd-messages[data-mode="compact"] .sd-para-long {
  margin-bottom: var(--sd-space-md) !important;
}

/* ── Dispatch Card (Agent Deployment) ────────────────────────────── */

@keyframes sd-dispatch-enter {
  from {
    opacity: 0;
    transform: translateY(12px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.sd-dispatch-card {
  background: #16162a;
  border: 1px solid #ffffff08;
  border-radius: 10px;
  padding: var(--space-lg);
  margin: var(--space-md) 0;
  animation: sd-dispatch-enter var(--duration-med) var(--ease-out-expo) both;
}

.sd-dispatch__header {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  font-weight: 400;
  color: #888;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  margin-bottom: var(--space-md);
}

.sd-dispatch__prompt {
  font-family: "IBM Plex Sans", var(--sd-font-sans);
  font-size: 13px;
  font-style: italic;
  color: var(--sd-text-secondary);
  line-height: 1.65;
  border-left: 2px solid var(--sd-accent);
  padding: var(--space-xs) var(--space-md);
  margin-bottom: var(--space-lg);
}

.sd-dispatch__rows {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.sd-dispatch__row {
  display: flex;
  align-items: center;
  gap: var(--space-sm);
  padding: var(--space-sm) var(--space-md);
  border-radius: 6px;
  transition: background var(--duration-fast) ease;
}

.sd-dispatch__row:hover {
  background: #ffffff06;
}

.sd-dispatch__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
}

.sd-dispatch__name {
  font-family: var(--sd-font-mono);
  font-size: 12px;
  font-weight: 700;
  color: var(--sd-text-primary);
  letter-spacing: 0.02em;
  min-width: 90px;
}

.sd-dispatch__role {
  font-family: "IBM Plex Sans", var(--sd-font-sans);
  font-size: 11px;
  color: var(--sd-text-muted);
  line-height: 1.65;
  flex: 1;
}

.sd-dispatch__status-area {
  margin-left: auto;
  flex-shrink: 0;
}

.sd-dispatch__status {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  letter-spacing: 0.01em;
  display: inline-flex;
  align-items: center;
  gap: 6px;
}

.sd-dispatch__status--waiting {
  color: var(--sd-text-muted);
}

.sd-dispatch__status--active {
  color: var(--sd-accent);
}

.sd-dispatch__status--complete {
  color: #81C784;
}

.sd-dispatch__status--error {
  color: #FF6E6E;
}

@keyframes sd-dispatch-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.3; }
}

.sd-dispatch__pulse-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--sd-accent);
  animation: sd-dispatch-pulse 1.2s ease-in-out infinite;
  flex-shrink: 0;
}

.sd-dispatch__duration {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  color: #555;
  margin-left: 6px;
}

.sd-dispatch__footer {
  font-family: var(--sd-font-mono);
  font-size: 11px;
  color: var(--sd-text-muted);
  text-align: center;
  padding-top: var(--space-md);
  margin-top: var(--space-md);
  border-top: 1px solid #ffffff08;
  letter-spacing: 0.01em;
}

/* ── Progress Panel ──────────────────────────────────────────────── */

.sd-progress-panel {
  background: #16162a;
  border: 1px solid #ffffff08;
  border-radius: 8px;
  padding: var(--space-md);
  margin: var(--space-sm) 0;
  display: flex;
  flex-direction: column;
  gap: var(--space-sm);
}

/* Level 1: Pipeline indicator */

.sd-progress-pipeline {
  display: flex;
  align-items: center;
  gap: 6px;
}

.sd-progress-pipeline__arrow {
  color: #ffffff15;
  font-size: 11px;
  user-select: none;
  flex-shrink: 0;
}

.sd-progress-stage {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  flex-shrink: 0;
}

.sd-progress-stage__dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  flex-shrink: 0;
  transition: background var(--duration-fast) ease,
              border-color var(--duration-fast) ease,
              box-shadow var(--duration-fast) ease;
}

.sd-progress-stage__label {
  font-family: var(--sd-font-mono);
  font-size: 10px;
  font-weight: 600;
  letter-spacing: 0.03em;
  transition: color var(--duration-fast) ease;
}

/* Waiting */
.sd-progress-stage--waiting .sd-progress-stage__dot {
  background: transparent;
  border: 1.5px solid #555;
}

.sd-progress-stage--waiting .sd-progress-stage__label {
  color: #555;
}

/* Active */
@keyframes sd-stage-pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.5; }
}

.sd-progress-stage--active .sd-progress-stage__dot {
  background: var(--stage-color);
  border: 1.5px solid var(--stage-color);
  box-shadow: 0 0 8px color-mix(in srgb, var(--stage-color) 50%, transparent);
  animation: sd-stage-pulse 1.5s ease-in-out infinite;
}

.sd-progress-stage--active .sd-progress-stage__label {
  color: var(--sd-text-primary);
}

/* Complete */
.sd-progress-stage--complete .sd-progress-stage__dot {
  background: transparent;
  border: 1.5px solid transparent;
}

.sd-progress-stage--complete .sd-progress-stage__dot::after {
  content: "\2713";
  font-size: 9px;
  color: #81C784;
  position: relative;
  top: -2px;
  left: -1px;
}

.sd-progress-stage--complete .sd-progress-stage__label {
  color: #666;
}

/* Error */
.sd-progress-stage--error .sd-progress-stage__dot {
  background: transparent;
  border: 1.5px solid transparent;
}

.sd-progress-stage--error .sd-progress-stage__dot::after {
  content: "\2717";
  font-size: 9px;
  color: #FF6E6E;
  position: relative;
  top: -2px;
  left: -1px;
}

.sd-progress-stage--error .sd-progress-stage__label {
  color: #FF6E6E;
}

/* Level 2: Progress bar */

.sd-progress-bar {
  height: 4px;
  background: #00BB8120;
  border-radius: 2px;
  overflow: hidden;
  position: relative;
}

.sd-progress-bar__fill {
  height: 100%;
  background: #00BB81;
  border-radius: 2px;
  transition: width 0.4s var(--ease-out-expo);
}

/* Indeterminate shimmer */
@keyframes sd-progress-shimmer {
  0% { transform: translateX(-100%); }
  100% { transform: translateX(300%); }
}

.sd-progress-bar--indeterminate .sd-progress-bar__fill {
  width: 30% !important;
  animation: sd-progress-shimmer 1.5s ease-in-out infinite;
}

/* Level 3: Node detail */

.sd-progress-detail {
  display: flex;
  justify-content: space-between;
  align-items: baseline;
  font-family: var(--sd-font-mono);
  font-size: 11px;
  color: #888;
  line-height: 1.65;
}

.sd-progress-detail__node {
  color: #e0e0e0;
}

.sd-progress-detail__right {
  color: #666;
  flex-shrink: 0;
}

/* ── Node FX (DOM overlay fallback) ──────────────────────────────── */

@keyframes sd-node-glow {
  0%, 100% {
    box-shadow: 0 0 8px #00BB8155, 0 0 15px #00BB8133;
    opacity: 0.8;
  }
  50% {
    box-shadow: 0 0 12px #00BB8188, 0 0 25px #00BB8155;
    opacity: 1;
  }
}

